import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"CZeroX App","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/app.md","filePath":"en/guide/app.md","lastUpdated":1785861127000}'),s={name:"en/guide/app.md"};function o(i,e,l,d,p,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="czerox-app" tabindex="-1">CZeroX App <a class="header-anchor" href="#czerox-app" aria-label="Permalink to &quot;CZeroX App&quot;">​</a></h1><p><strong>CZeroX</strong> is CZero&#39;s native companion app, built with Jetpack Compose (Miuix style), that reads and writes the module&#39;s <code>config.json</code> and its rule JSON files directly. It is the module&#39;s only graphical configuration frontend — no WebUI.</p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p>Grab the latest APK from the <a href="/en/download">download page</a> or <a href="https://github.com/Xocio/CZero/releases" target="_blank" rel="noreferrer">Releases</a>. Keeping the module and the app on the same version is recommended.</p><h2 id="three-tabs" tabindex="-1">Three tabs <a class="header-anchor" href="#three-tabs" aria-label="Permalink to &quot;Three tabs&quot;">​</a></h2><p>The app is split into <strong>Home / Storage / Settings</strong>.</p><h3 id="home" tabindex="-1">Home <a class="header-anchor" href="#home" aria-label="Permalink to &quot;Home&quot;">​</a></h3><ul><li><strong>Runtime status</strong> — whether the scheduler is running and how much memory it uses; restart it in one tap if it isn&#39;t.</li><li><strong>Cleaning stats</strong> — space freed today and in total, plus execution counts for per-app cleaning, empty folders, suppression and garbage collection. Tapping through opens <strong>Cleaning trends</strong>, charting daily freed space over 7 / 30 days.</li><li><strong>F2FS status</strong> — live segment usage.</li><li><strong>One-tap actions</strong> — clean now, clean a single app, background suppression, F2FS garbage collection, empty-folder cleanup. Progress and results are shown via notifications, including the Dynamic Island.</li></ul><h3 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h3><p>A panel unrelated to cleaning, but concerned with the same storage device:</p><ul><li><strong>Device lifespan</strong> — shows the UFS / eMMC life level and reserved-block warning, translated into a remaining-life range.</li><li><strong>Live read/write throughput</strong> — current throughput curve and cumulative bytes.</li><li><strong>Benchmark</strong> — sequential reads/writes, random reads/writes and database transactions, combined into one score. If results vary too much across rounds, it suggests re-running.</li><li><strong>Device info</strong> — type, model, vendor, firmware and capacity.</li></ul><div class="tip custom-block"><p class="custom-block-title">Lifespan data is read-only</p><p>Lifespan and device info are read-only and write nothing to the storage device. The benchmark does perform real reads and writes on a test file, which is cleaned up afterwards.</p></div><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p>Covers every field in <code>config.json</code>, grouped. Saving takes effect immediately — no reboot.</p><table tabindex="0"><thead><tr><th>Group</th><th>Contains</th></tr></thead><tbody><tr><td><strong>Cleaning</strong></td><td>Basic cleaning, GC, background suppression (and its target app list), empty-folder cleanup (and its whitelist), enhanced cleaning, recycle bin</td></tr><tr><td><strong>Rules</strong></td><td>Custom rules (built-in rules + rule sources), cleaning whitelist, per-app cache cleaning</td></tr><tr><td><strong>Fine-grained suppression</strong></td><td>Suppression switches and capability probing, list of apps to suppress</td></tr><tr><td><strong>Other</strong></td><td>Logging, app settings (language / theme), backup &amp; restore</td></tr></tbody></table><h2 id="main-pages" tabindex="-1">Main pages <a class="header-anchor" href="#main-pages" aria-label="Permalink to &quot;Main pages&quot;">​</a></h2><h3 id="rule-editor-and-rule-sources" tabindex="-1">Rule editor and rule sources <a class="header-anchor" href="#rule-editor-and-rule-sources" aria-label="Permalink to &quot;Rule editor and rule sources&quot;">​</a></h3><p>Manages custom cleaning paths, the cleaning whitelist and the empty-folder sweep scope. Rules are organized into groups that can be toggled as a whole and reordered.</p><p>Beyond the built-in rules, you can subscribe to third-party <strong>rule sources</strong>, which update once a day and appear as their own card. To publish one yourself, see <a href="/en/guide/rule-source">Authoring Rule Sources</a>.</p><h3 id="per-app-cache-cleaning" tabindex="-1">Per-app cache cleaning <a class="header-anchor" href="#per-app-cache-cleaning" aria-label="Permalink to &quot;Per-app cache cleaning&quot;">​</a></h3><p>Browse each path&#39;s real disk usage per app and add or remove entries; pull community-verified rules from the <strong>shared cloud library</strong>, or submit your own for review. Approved rules enter the public rule snapshot available to every user.</p><h3 id="recycle-bin" tabindex="-1">Recycle bin <a class="header-anchor" href="#recycle-bin" aria-label="Permalink to &quot;Recycle bin&quot;">​</a></h3><p>Browse cleaning records (file count, size, expiry) and restore mistakenly removed files to their original location in one tap. Cleaned files are kept 7 days by default, adjustable via <code>general.recycle_keep_days</code>. See <a href="/en/guide/features#recycle-bin-restore">Features · Recycle bin &amp; restore</a>.</p><h3 id="fine-grained-suppression" tabindex="-1">Fine-grained suppression <a class="header-anchor" href="#fine-grained-suppression" aria-label="Permalink to &quot;Fine-grained suppression&quot;">​</a></h3><p>Suppresses background apps without terminating them — state is kept, and they resume instantly. The page first probes what this device supports (system version, kernel support, the current state of the switches, and how many processes are actually suppressed), mapping to the <code>freezer</code> section of <code>config.json</code>.</p><p>A separate <strong>apps to suppress</strong> page lists, for each app, how many processes it has, how many are suppressed, and how much memory they hold, so you can pick per app.</p><div class="tip custom-block"><p class="custom-block-title">How it differs from &quot;background suppression&quot; on Home</p><p>The one-tap background suppression on Home terminates processes; this one suspends without killing. See <a href="/en/guide/features#fine-grained-suppression">Features · Fine-grained suppression</a>.</p></div><h3 id="backup-restore" tabindex="-1">Backup &amp; restore <a class="header-anchor" href="#backup-restore" aria-label="Permalink to &quot;Backup &amp; restore&quot;">​</a></h3><p>Exports the configuration and all rules into a single file, and imports it back in one tap after a device change or a reflash.</p><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h2><p>CZeroX supports <strong>Simplified Chinese</strong> and <strong>English</strong>, following the system setting or switchable in-app.</p><h2 id="relationship-to-the-module" tabindex="-1">Relationship to the module <a class="header-anchor" href="#relationship-to-the-module" aria-label="Permalink to &quot;Relationship to the module&quot;">​</a></h2><p>CZeroX performs no cleaning itself — it only <strong>reads and writes the configuration and displays status</strong>; the actual scheduling and cleaning is done by the module. So the module works fine on its defaults even without CZeroX installed; the app&#39;s value is making configuration and inspection intuitive.</p>',33)])])}const g=a(s,[["render",o]]);export{h as __pageData,g as default};
